export function zweryfikujLink(tokenHash: string, typ: TypPotwierdzenia): Promise<WynikAkcjiAuth> {
  if (tokenHash === '') return Promise.resolve(LINK_NIEPOPRAWNY)
  const klucz = `${typ}:${tokenHash}`
  if (biezacaWeryfikacja?.klucz !== klucz) {
    const zwolnij = () => {
      if (biezacaWeryfikacja?.klucz === klucz) biezacaWeryfikacja = null
    }
    const wynik = weryfikujLink(tokenHash, typ).then(
      (rezultat) => {
        if (rezultat.wynik === 'blad' && rezultat.kod === 'siec') zwolnij()
        return rezultat
      },
      (blad: unknown) => {
        zwolnij()
        throw blad
      },
    )
    biezacaWeryfikacja = { klucz, wynik }
  }
  return biezacaWeryfikacja.wynik
}
